window.POETRY_REGISTER("v4-pairs-2-16-0.js",{"poems":[["前言","王重民辑录，刘修业整理。","唐","唐诗",51967,"v4-poems-51.js",967],["琵琶泓石壁诗刻（按《山西通志》《山右金石记》卷九著录《》，谓「诗七古一首，见《鳯台县志》。」检《全唐诗》无考卷有权澈五言《题沈黎城》一首。此七古《琵琶泓诗》，盖未收。）","权澈","唐","唐诗",52301,"v4-poems-52.js",301],["题云居上寺（并序）","吉逾","唐","唐诗",52335,"v4-poems-52.js",335]],"pairs":[["最近","我在整理有三辑录的敦煌残卷诗集时",0,"","我在整理有三輯錄的敦煌殘卷詩集時",0],["疑误","第十五句琵琶泓石壁诗刻宦积作宣清",1,"疑誤","第十五句琵琶泓石壁詩刻宦積作宣清",0],["果尔","则自辛酉赋诗以迄元和四年己丑刻石",2,"果爾","則自辛酉賦詩以迄元和四年己丑刻石",0]]});
